<?php $storeIndex = $storesById ?? array_column(app('storeRepository')->all(), null, 'id'); ?>
<div class="latest-list"><?php foreach ($offers as $offer): ?><?php $store = $storeIndex[(int) $offer['store_id']] ?? null; ?><a class="latest-item" href="<?php echo e(url('/coupon/' . $offer['slug'])); ?>"><div class="mini-logo"><?php echo e($store['initial'] ?? '?'); ?></div><div class="latest-info"><strong><?php echo e($offer['title']); ?></strong><small><?php echo e($store['name'] ?? 'Store'); ?> · <?php echo e($offer['type']); ?></small></div><div class="latest-discount"><?php echo e($offer['discount']); ?></div></a><?php endforeach; ?></div>
